def objs(g,colors):
    from collections import deque
    seen=set(); out=[]
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j] in colors and (i,j) not in seen:
                q=deque([(i,j)]); comp=[(i,j)]; seen.add((i,j))
                while q:
                    y,x=q.popleft()
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<len(g) and 0<=nx<len(g[0]) and g[ny][nx] in colors and (ny,nx) not in seen:
                                seen.add((ny,nx)); q.append((ny,nx)); comp.append((ny,nx))
                out.append(comp)
    return out
